package telemetry

import (
	"context"

	"github.com/gin-gonic/gin"
	"go.opentelemetry.io/otel/trace"
)

const CorrelationIDHeader = "X-Correlation-ID"

// Define a private key type to prevent collision in context values.
type correlationIDKey struct{}

// CorrelationMiddleware reads the incoming X-Correlation-ID (generated by NGINX)
// and stores it in the Gin context. It also injects it into the standard request
// context so downstream services can access it.
// If no header is present, it falls back to the OTel trace ID.
func CorrelationMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		correlationID := c.GetHeader(CorrelationIDHeader)
		if correlationID == "" {
			span := trace.SpanFromContext(c.Request.Context())
			sc := span.SpanContext()
			if sc.IsValid() {
				correlationID = sc.TraceID().String()
			}
		}
		c.Set("correlation_id", correlationID)
		c.Header(CorrelationIDHeader, correlationID)

		// Propagate via standard request context.Context
		ctx := context.WithValue(c.Request.Context(), correlationIDKey{}, correlationID)
		c.Request = c.Request.WithContext(ctx)

		c.Next()
	}
}

// BuildObservabilityHeaders constructs propagation headers for outgoing HTTP requests.
// This matches the Python microservices implementation format.
func BuildObservabilityHeaders(c *gin.Context) map[string]string {
	headers := make(map[string]string)
	if id, exists := c.Get("correlation_id"); exists {
		headers[CorrelationIDHeader] = id.(string)
	}
	span := trace.SpanFromContext(c.Request.Context())
	sc := span.SpanContext()
	if sc.IsValid() {
		headers["traceparent"] = "00-" + sc.TraceID().String() +
			"-" + sc.SpanID().String() + "-01"
	}
	return headers
}

// BuildObservabilityHeadersFromContext constructs propagation headers from a standard context.Context.
// This is used in downstream service layers where Gin's *gin.Context is not directly available.
func BuildObservabilityHeadersFromContext(ctx context.Context) map[string]string {
	headers := make(map[string]string)

	// If it's a gin.Context, delegate to BuildObservabilityHeaders
	if c, ok := ctx.(*gin.Context); ok {
		return BuildObservabilityHeaders(c)
	}

	// Try extracting correlation ID from context values
	var correlationID string
	if val := ctx.Value(correlationIDKey{}); val != nil {
		if idStr, ok := val.(string); ok {
			correlationID = idStr
		}
	}

	span := trace.SpanFromContext(ctx)
	sc := span.SpanContext()

	// Fallback to trace ID if no correlation ID was found
	if correlationID == "" && sc.IsValid() {
		correlationID = sc.TraceID().String()
	}

	if correlationID != "" {
		headers[CorrelationIDHeader] = correlationID
	}

	if sc.IsValid() {
		headers["traceparent"] = "00-" + sc.TraceID().String() +
			"-" + sc.SpanID().String() + "-01"
	}
	return headers
}
